<div class="wa-project-editor" x-data="{ get draft() { return $store.pagePreview.ensure(tab.id, tab.pageId); } }">
    <header class="wa-project-toolbar"><div><span class="wa-project-eyebrow">EDITOR STRÁNKY · NÁHĽAD</span><h1 x-text="draft.data.name || tab.title"></h1><p class="wa-project-muted"><span x-text="draft.data.project_name"></span> / <span x-text="draft.data.domain_name"></span></p></div><button type="button" class="btn wa-project-secondary" @click="$store.pagePreview.load(tab.id)" :disabled="draft.loading">Obnoviť náhľad</button></header>
    <p x-show="draft.loading" class="wa-project-message" role="status">Vykresľujem stránku z komponentov…</p>
    <p x-show="draft.error" class="wa-project-message is-error" role="alert" x-text="draft.error"></p>
    <div x-show="draft.loaded" class="wa-component-preview"><iframe :data-wa-preview="tab.id" title="Náhľad stránky z komponentov" sandbox="" referrerpolicy="no-referrer" :srcdoc="draft.preview"></iframe></div>
    <section class="wa-project-card mt-4"><h2>Komponenty stránky</h2><p class="wa-project-muted" x-show="!draft.data.components.length">Do stránky zatiaľ nebol vložený komponent. Vyberte komponent v knižnici a použite Vložiť do projektu.</p><template x-for="component in draft.data.components" :key="component.id"><button type="button" class="wa-domain-list-item" @click="$dispatch('add-new-tab', { title: component.name, mode: 'component', componentId: component.id, componentPath: 'cms/' + component.id + '.json' })"><span x-text="component.name"></span><span>Verzia <span x-text="component.revision"></span> · Upraviť</span></button></template></section>
</div>
